/*
 * Mock source documents of the split reader (Etappe 2), keyed by knowledge item id.
 * The files are generated by scripts/make-mock-docs.mjs; page numbers, EPUB anchors and the seed
 * highlight text must match what that script writes. Live items get their ReaderDoc from
 * liveDoc.ts (file URL signed from Supabase Storage, position from reading_state).
 */

export type ReaderFormat = "pdf" | "epub";

/** One row of item_highlights: quote_text, note_text and the locator (book page, EPUB CFI). */
export interface ReaderHighlight {
  id: string;
  text: string;
  /** Set for "Eigene Notizen": a note anchored to the quoted passage. */
  note?: string;
  page: number;
  /** EPUB CFI range when the passage was marked in the EPUB. */
  cfi?: string;
  createdAt: string;
}

/** knowledge_items.reading_state */
export interface ReadingState {
  format: ReaderFormat;
  page: number;
  cfi?: string;
  /** 0..1 through the whole book (page / totalPages). */
  progress: number;
  updatedAt: string;
}

export interface ReaderDoc {
  noteId: string;
  folder: string;
  /** Formats the document exists in (one format tab each); the first is the default. */
  formats: ReaderFormat[];
  /** File name per format, shown in the breadcrumb. */
  fileName: Partial<Record<ReaderFormat, string>>;
  /** Document URL per format; empty for a live doc until its signed URL arrives. */
  url: Partial<Record<ReaderFormat, string>>;
  /** Live item: the file URL is signed on demand (lib/api/reader-actions.ts). */
  live?: boolean;
  /** Book page numbers are known (false for an EPUB without page anchors: positions are CFIs). */
  paged: boolean;
  /** PDF page index (1-based) + pageOffset = printed book page. */
  pageOffset: number;
  firstPage: number;
  /** 0 = unknown (live PDF without page_count until pdf.js has loaded it, EPUB without anchors). */
  lastPage: number;
  totalPages: number;
  /** Page the chapter synthesis points to ("Springe zu Seite 42"). */
  anchorPage: number;
  /** EPUB href of each book page's anchor element. */
  epubAnchors: Record<number, string>;
  seedHighlights: ReaderHighlight[];
  /** Mock answer of "Erklären" (prototype copy); null hides "Erklären". */
  explanation: string | null;
  /** knowledge_items.reading_state from the snapshot (live docs). */
  savedState?: ReadingState | null;
}

const AI_ENGINEERING: ReaderDoc = {
  noteId: "n3",
  folder: "60_Documents",
  formats: ["pdf", "epub"],
  paged: true,
  fileName: { pdf: "AI_Engineering.pdf", epub: "AI_Engineering.epub" },
  url: { pdf: "/mock/docs/ai-engineering-ch3.pdf", epub: "/mock/docs/ai-engineering-ch3.epub" },
  pageOffset: 40,
  firstPage: 41,
  lastPage: 44,
  totalPages: 318,
  anchorPage: 42,
  epubAnchors: {
    41: "chapter-2.xhtml#page-41",
    42: "chapter-3.xhtml#page-42",
    43: "chapter-3.xhtml#page-43",
    44: "chapter-3-reranking.xhtml#page-44",
  },
  seedHighlights: [
    {
      id: "seed-n3-1",
      text: "Contextual retrieval puts a short, model-written description in front of every chunk before it is embedded, placing it within the whole document.",
      page: 42,
      createdAt: "2026-10-21T21:34:00.000Z",
    },
  ],
  explanation:
    "Imagine every index card gets a slip on top: \u201cThis card comes from the 2024 quarterly report, revenue section.\u201d Search then finds the card even for vague questions, because the slip supplies the missing information.",
};

const READER_DOCS: Record<string, ReaderDoc> = { n3: AI_ENGINEERING };

export function readerDoc(id: string): ReaderDoc | undefined {
  return READER_DOCS[id];
}

export const readerDocIds = (): string[] => Object.keys(READER_DOCS);
